           }

           this.WARCs.push(file)
         }
       }
       if (this.WARCs.length < 1) {
         throw new Error('No WARC found.')
       }
     } catch (err) {
       log.trace(err)
       throw new Error('"input" must be a valid path leading to at least 1 .warc or .warc.gz file.')
     }

